-- Fictional teaching data only. Run as a database administrator, once.
-- IDs are generated by the database and carried through local variables.
begin;
do $$
declare r uuid; produce uuid; cold uuid; tomato uuid; rice uuid; chicken uuid; eggs uuid; milk uuid;
  po uuid; tl uuid; rl uuid; receipt uuid; received_line uuid;
begin
  if exists(select 1 from public.restaurants where is_demo and name='Demo Restaurant - NYC') then
    raise notice 'Demo already exists; no data changed'; return;
  end if;
    values(r,'DEMO - Metro Produce','produce@example.invalid',2) returning id into produce;
    values(r,'DEMO - City Cold Supply','cold@example.invalid',1) returning id into cold;
    values(r,'TOMATO','Tomatoes','Produce','kg',10) returning id into tomato;
    values(r,'RICE','Rice','Dry goods','kg',10) returning id into rice;
    values(r,'CHICKEN','Chicken breast','Meat','kg',6) returning id into chicken;
    values(r,'EGGS','Eggs','Dairy and eggs','each',48) returning id into eggs;
    values(r,'MILK','Milk','Dairy and eggs','l',5) returning id into milk;
    values(r,produce,'DEMO-PO-001','partially_received','Fictional order: tomatoes arrive in two deliveries.') returning id into po;
    values(r,po,tomato,20,2.50,'kg') returning id into tl;
    values(r,po,rice,10,3,'kg') returning id into rl;
    values(r,po,'DEMO first delivery: 12 kg tomatoes and 10 kg rice',gen_random_uuid(),'{"demo":true}') returning id into receipt;
    values(r,receipt,po,tl,tomato,12) returning id into received_line;
    values(r,tomato,'receipt',12,received_line,'DEMO received DEMO-PO-001',gen_random_uuid());
    values(r,receipt,po,rl,rice,10) returning id into received_line;
    values(r,rice,'receipt',10,received_line,'DEMO received DEMO-PO-001',gen_random_uuid());
end;
$$;
commit;
select name,quantity_on_hand,base_unit,reorder_point,is_low_stock from public.inventory_levels order by name;
